import{_ as t,o as s,c as i,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"A Glimpse of the New Ceph Messenger Built on Seastar - Yingxin Cheng & Vivian Zhu, Intel","description":"","frontmatter":{"title":"A Glimpse of the New Ceph Messenger Built on Seastar - Yingxin Cheng & Vivian Zhu, Intel","date":"2019-05-24T00:00:00.000Z","updated":"2019-05-24T00:00:00.000Z","tags":["Ceph","分布式存储","Seastar","性能优化","Crimson Messenger"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/A_Glimpse_of_the_New_Ceph_Messenger_Built_on_Seastar_-_Yingxin_Cheng_Vivian_Zhu_Intel.md","filePath":"posts/2019/A_Glimpse_of_the_New_Ceph_Messenger_Built_on_Seastar_-_Yingxin_Cheng_Vivian_Zhu_Intel.md","lastUpdated":1780459816000}'),r={name:"posts/2019/A_Glimpse_of_the_New_Ceph_Messenger_Built_on_Seastar_-_Yingxin_Cheng_Vivian_Zhu_Intel.md"};function l(o,e,a,_,p,g){return s(),i("div",null,[...e[0]||(e[0]=[n('<h3 id="改进后的中文总结" tabindex="-1">改进后的中文总结 <a class="header-anchor" href="#改进后的中文总结" aria-label="Permalink to &quot;改进后的中文总结&quot;">​</a></h3><p>会议纪要</p><p><strong>会议时间</strong>： 2023年X月X日</p><p><strong>会议主题</strong>： Ceph 新消息传递组件（Crimson Messenger）基于 Seastar 的开发进展</p><p><strong>参会人员</strong>： Intel，Ceph 团队成员</p><p><strong>会议内容</strong>：</p><p><strong>一、背景介绍</strong></p><ul><li>Ceph 核心对象层重构项目（Crimson）旨在提升在现代硬件上的性能。</li><li>现代硬件特点：多核心、NUMA 架构、高速存储设备（如 NVMe SSD、持久内存）、高速网络。</li><li>SAP 架构和 POSIX 线程存在性能瓶颈，需要优化。</li></ul><p><strong>二、Crimson Messenger 的目标</strong></p><ol><li>利用 C++ Star 框架实现同步编程，统一架构。</li><li>实现跨核心通信的最小化，建立直接核心到核心连接。</li><li>利用 C++ Star 框架进行性能验证和优化。</li></ol><p><strong>三、Crimson Messenger 的设计</strong></p><ol><li>基于 C++ Star 框架，实现异步 I/O、任务调度、网络堆栈等功能。</li><li>实现直接核心到核心连接，减少跨核心通信。</li><li>利用 C++ Star 框架的异步编程模型，实现代码简洁、易于维护。</li></ol><p><strong>四、性能测试</strong></p><ul><li>与现有异步消息传递组件进行性能对比，Crimson Messenger 在大部分场景下性能更优。</li><li>利用 C++ Star 框架的异步编程模型，实现代码简洁、易于维护。</li></ul><p><strong>五、挑战和未来工作</strong></p><ol><li>C++ Star 框架的功能不够完善，可能需要定制化实现。</li><li>需要深入了解 C++ Star 框架的编程模型，才能正确实现代码。</li><li>需要持续优化性能，并确保可靠性。</li></ol><p><strong>六、行动计划</strong></p><ol><li>完成 Crimson Messenger 的核心功能。</li><li>进行性能测试和优化。</li><li>评估 C++ Star 框架的定制化需求。</li><li>将 Crimson Messenger 集成到 Ceph 中。</li></ol><p><strong>七、总结</strong></p><p>Crimson Messenger 是 Ceph 核心对象层重构项目的重要组成部分，旨在提升 Ceph 在现代硬件上的性能。目前，Crimson Messenger 已取得初步进展，但仍面临一些挑战。未来，Ceph 团队将继续努力，确保 Crimson Messenger 的成功应用。</p><h3 id="错误、误解或遗漏的信息" tabindex="-1">错误、误解或遗漏的信息 <a class="header-anchor" href="#错误、误解或遗漏的信息" aria-label="Permalink to &quot;错误、误解或遗漏的信息&quot;">​</a></h3><ul><li>原始字幕中提到的 &quot;Seastar&quot; 应为 &quot;C++ Star&quot;，是 Seastar 框架的简称。</li><li>原始字幕中未提及的具体技术细节，如 C++ Star 框架的具体功能和优势，在总结中有所体现。</li><li>原始字幕中提到的 &quot;Crimson OSD&quot; 和 &quot;Crimson Messenger&quot; 的关系，在总结中得到了强调。</li></ul>',22)])])}const u=t(r,[["render",l]]);export{h as __pageData,u as default};
